<?php
namespace App\Http\Middleware;
use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;
class SecurityHeaders { public function handle(Request $request,Closure $next):Response{$response=$next($request);$response->headers->set('X-Content-Type-Options','nosniff');$response->headers->set('X-Frame-Options','DENY');$response->headers->set('X-Permitted-Cross-Domain-Policies','none');$response->headers->set('X-Download-Options','noopen');$response->headers->set('Referrer-Policy','strict-origin-when-cross-origin');$response->headers->set('Permissions-Policy','camera=(), microphone=(), geolocation=(), payment=(), usb=()');$response->headers->set('Cross-Origin-Opener-Policy','same-origin');$response->headers->set('Cross-Origin-Resource-Policy','same-origin');$response->headers->set('Content-Security-Policy',"default-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'; object-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data:; media-src 'self' https://cdn.coverr.co; connect-src 'self'");if($request->is('api/*')||$request->is('login','register','forgot-password','dashboard*'))$response->headers->set('Cache-Control','no-store, private');if(app()->isProduction()&&$request->isSecure())$response->headers->set('Strict-Transport-Security','max-age=31536000; includeSubDomains; preload');return $response;} }
